package dev.chipsxo.chipscritters;
import java.util.*;import com.google.gson.*;
final class Patch64RegressionTests {
 static void check(boolean ok,String message){if(!ok)throw new AssertionError("0.1.64: "+message);}
 static void run()throws Exception{
  String lobby="{\"server\":\"dynamiclobby1G\",\"gametype\":\"MAIN\",\"lobbyname\":\"lobby3\"}";
  String limbo="{\"server\":\"limbo\"}";
  String island="{\"server\":\"mini187DN\",\"gametype\":\"SKYBLOCK\",\"mode\":\"dynamic\",\"map\":\"Private Island\"}";
  String safari="{\"server\":\"mini1\",\"gametype\":\"SKYBLOCK\",\"mode\":\"safari\"}";
  for(String reply:List.of(lobby,limbo,island,safari)){var info=LobbyInfoRules.parse(reply);check(info!=null,"valid optional-field locraw");var session=new LobbyInfoSession();session.automaticRequestSent(10000);check(session.accept(reply,10001).hideReply(),"automated or other-mod reply hidden");check(session.confirmed()&&!session.requestDue(90000,true,true),"any valid reply ends retries");}
  check(!LobbyInfoRules.isCritterSafari(LobbyInfoRules.parse(lobby))&&!LobbyInfoRules.isCritterSafari(LobbyInfoRules.parse(limbo))&&!LobbyInfoRules.isCritterSafari(LobbyInfoRules.parse(island)),"non-Safari replies do not start routes");check(LobbyInfoRules.isCritterSafari(LobbyInfoRules.parse(safari)),"Safari requires exact gametype+mode, not map");
  for(String text:List.of("Party > Alex: "+lobby,"hello",lobby+" trailing","{\"server\":1}","{\"server\":\"mini\",\"gametype\":null}","{\"server\":\"mini\",\"server\":\"other\"}","{\"server\":\"mini\",\"message\":\"normal chat\"}","{\"mode\":\"safari\"}","{\"server\":\"mini\",}"))check(LobbyInfoRules.parse(text)==null,"malformed/normal chat stays visible");
  var session=new LobbyInfoSession();session.manualRequestSent(10000);check(!session.accept(lobby,10001).hideReply(),"explicit /sr locraw reply visible");check(session.accept(lobby,10002).hideReply(),"debug visibility consumed once");session.manualRequestSent(20000);session.resetForWorldChange();check(session.accept(limbo,20001).hideReply(),"world reset removes stale visible request");session.manualRequestSent(30000);check(session.accept(limbo,60001).hideReply(),"expired request cannot reveal later reply");
  var other=new LobbyInfoSession();check(other.accept(lobby,1).hideReply(),"other mod command has no explicit debug provenance");
  var event=net.fabricmc.fabric.api.event.EventFactory.createArrayBacked(net.fabricmc.fabric.api.client.message.v1.ClientReceiveMessageEvents.AllowGame.class,handlers->(message,overlay)->{for(var h:handlers)if(!h.allowReceiveGameMessage(message,overlay))return false;return true;});
  var early=net.minecraft.resources.Identifier.fromNamespaceAndPath("chipscritters_test","observe");var late=net.minecraft.resources.Identifier.fromNamespaceAndPath("chipscritters_test","hide");int[] called={0};event.addPhaseOrdering(early,net.fabricmc.fabric.api.event.Event.DEFAULT_PHASE);event.addPhaseOrdering(net.fabricmc.fabric.api.event.Event.DEFAULT_PHASE,late);
  event.register(late,(m,o)->false);event.register((m,o)->{called[0]++;return true;});event.register(early,(m,o)->{called[0]++;return true;});check(!event.invoker().allowReceiveGameMessage(net.minecraft.network.chat.Component.literal(lobby),false)&&called[0]==2,"observe and default listeners run before late hide");
  var timer=new DoomspiralCountdown();timer.message(DoomspiralCountdown.SUMMON,10000);check(DoomspiralCountdown.READY_DELAY_MILLIS==6000&&!timer.ready(15999)&&timer.ready(16000),"six-second threshold");check(timer.notifyOnce(16000)&&!timer.notifyOnce(16001),"ready cue once");timer.reset();timer.message(DoomspiralCountdown.SUMMON,10000);timer.message("You threw a Masterful Critter Capsule at the Doomspiral!",15000);check(timer.ready(15000),"earlier throw still proves ready");
  var pair=java.security.KeyPairGenerator.getInstance("Ed25519").generateKeyPair();String pub=java.util.Base64.getEncoder().encodeToString(pair.getPublic().getEncoded());var payload=new JsonObject();payload.addProperty("schema",1);payload.addProperty("dataVersion",1);payload.addProperty("minModVersion","0.1.64");try(var in=Patch64RegressionTests.class.getResourceAsStream("/data/chipscritters/routes.json")){payload.add("routes",JsonParser.parseReader(new java.io.InputStreamReader(in,java.nio.charset.StandardCharsets.UTF_8)));}payload.add("recordedPaths",new JsonArray());String envelope=SignedRouteRegressionTests.envelope(payload,pair.getPrivate());var good=RouteUpdateResponse.verify(200,envelope,pub,"0.1.64",0);
  var state=new RouteUpdateState();state.loadCache(good);
  for(int status:new int[]{404,500,0}){try{state.stage(RouteUpdateResponse.verify(status,null,pub,"0.1.64",1));throw new AssertionError("accepted missing/offline response");}catch(java.io.IOException expected){}check(state.active()==good&&state.pending()==null,"missing/offline preserves last good");}
  try{state.stage(RouteUpdateResponse.verify(200,"not JSON",pub,"0.1.64",1));throw new AssertionError("accepted invalid update");}catch(RuntimeException expected){}check(state.active()==good,"invalid update preserves last good");
  var fresh=new RouteUpdateState();try{fresh.stage(RouteUpdateResponse.verify(404,null,pub,"0.1.64",0));}catch(java.io.IOException expected){}check(fresh.active()==null,"fresh missing update keeps bundled routes");
  payload.addProperty("dataVersion",2);var next=RouteUpdateResponse.verify(200,SignedRouteRegressionTests.envelope(payload,pair.getPrivate()),pub,"0.1.64",1);state.stage(next);check(!state.beginRun(true)&&state.active()==good,"valid update cannot change active run");check(state.beginRun(false)&&state.active()==next,"new run can apply valid signed data");
  check(ReleaseLinks.ROUTES.equals("https://raw.githubusercontent.com/chipsxo/ChipsCritters/main/routes-signed.json"),"read-only route URL");
  for(int gap:new int[]{999,1000,1001}){int expected=gap<1000?0:1;check(ShardValueRule.compare(2000+gap,2000,0,0,1000)==expected,"sell boundary "+gap);check(ShardValueRule.compare(2000,2000+gap,0,0,1000)==-expected,"salvage boundary "+gap);}
  check(ShardValueRule.compare(4000/0.99,3000,0,1,1000)==1,"fee-adjusted exact 1000 difference passes");
  var legacy=new JsonObject();legacy.addProperty("minimumShardAdvantagePercent",7.5);check(ShardProfitMinimum.applyDefault(legacy)&&legacy.get("minimumShardAdvantageCoins").getAsDouble()==1000&&legacy.get("minimumShardAdvantagePercent").getAsDouble()==7.5,"legacy gains 1000 coins, custom percentage preserved");
  for(double custom:new double[]{0,500,2500,15000}){var saved=new JsonObject();saved.addProperty("minimumShardAdvantageCoins",custom);check(!ShardProfitMinimum.applyDefault(saved)&&saved.get("minimumShardAdvantageCoins").getAsDouble()==custom,"custom saved coin minimum kept "+custom);}
  check(ShardProfitMinimum.DEFAULT_COINS==1000,"fresh/default/reset 1000");
  System.out.println("0.1.64 checks passed: lobby/limbo/Private Island/Safari locraw; strict normal-chat rejection; bounded retries/stale provenance; explicit debug visibility; late Fabric phase preserves default listeners; 6-second timer/early throw; signed missing/invalid/offline fallback and run-boundary staging.");
 }
}
